signal.x = 0:0.01:1;

signal.y = sin(2*pi*signal.x);

signal.title = 'f(x) = sin(2*pi*x)';

figure; %[output:27678d75]
plot(signal.x, signal.y, 'b', 'LineWidth', 1.5); %[output:27678d75]
grid on; %[output:27678d75]

title(signal.title); %[output:27678d75]
xlabel('x'); %[output:27678d75]
ylabel('f(x)'); %[output:27678d75]
%%
while true %[output:group:4ce88756]
    m = input('Enter value for m: ');
    n = input('Enter value for n: ');

    if m == n
        disp('m and n are equal. Exiting program.');
        break;
    end

    while true
        if m > n
            diff = m - n;
            m = diff;
        else
            diff = n - m;
            n = diff;
        end

        if diff <= 0
            break;
        end

        disp(['Result of subtraction: ', num2str(diff)]); %[output:80725342]
    end
end %[output:group:4ce88756]
%%
A = [];
B = [];

while true
    a = round(rand*3);
    b = round(rand*5);

    A(end+1) = a;
    B(end+1) = b;

    if a == b
        break;
    end
end

disp('Array A:'); %[output:24505ecf]
disp(A); %[output:7f953c81]

disp('Array B:'); %[output:9a891920]
disp(B); %[output:9d633d1b]
%[output:2e04b656]
plot(1:length(A), A, 'b-o'); %[output:2e04b656]
hold on; %[output:2e04b656]
plot(1:length(B), B, 'r-o'); %[output:2e04b656]
hold off; %[output:2e04b656]

grid on; %[output:2e04b656]
xlabel('Iteration'); %[output:2e04b656]
ylabel('Random number'); %[output:2e04b656]
title('Changes in Two Random Number Sequences'); %[output:2e04b656]
legend('A = round(rand*3)', ... %[output:group:3a8f8167] %[output:2e04b656]
    'B = round(rand*5)', ... %[output:2e04b656]
    'Location', 'best'); %[output:group:3a8f8167] %[output:2e04b656]

